+            let warns = generated(&world, &mut h, whole(), params.clone(), area.clone());
+            assert!(gouges(&warns) > 0, "{label} {tag} rotated {rotated}: convicted on the op: {warns:?}");
+            assert_post_refused(&world, &format!("{tag}-{label}-{rotated}"), rotated);
+        }
+    }
+}
